    static class Product {
        String category,name,spec;
        Product(String c,String n,String s){category=c;name=n;spec=s;}
        String display(){return name+(spec.isEmpty()?"":" · "+spec);}
        String searchable(){return (category+" "+name+" "+spec).toLowerCase(Locale.ROOT);}
    }
    static class LineItem {
        String category,name,spec,qty,price;
        LineItem(String a,String b,String c,String d,String e){category=a;name=b;spec=c;qty=d;price=e;}
        JSONObject json(){JSONObject o=new JSONObject();try{o.put("category",category);o.put("name",name);o.put("spec",spec);o.put("qty",qty);o.put("price",price);}catch(Exception ignored){}return o;}
        static LineItem from(JSONObject o){return new LineItem(o.optString("category"),o.optString("name"),o.optString("spec"),o.optString("qty","1"),o.optString("price"));}
    }
    static class Draft {
        String id="", client="", phone="", location="", date="", system="Hybrid", capacity="", phase="Single phase", organizer="", notes="";
        boolean installation=true, transport=false;
        ArrayList<LineItem> items=new ArrayList<>();
        ArrayList<String> photos=new ArrayList<>();
        JSONObject json(){JSONObject o=new JSONObject();try{
            o.put("id",id);o.put("client",client);o.put("phone",phone);o.put("location",location);o.put("date",date);o.put("system",system);o.put("capacity",capacity);o.put("phase",phase);o.put("organizer",organizer);o.put("notes",notes);o.put("installation",installation);o.put("transport",transport);
            JSONArray a=new JSONArray();for(LineItem x:items)a.put(x.json());o.put("items",a);JSONArray p=new JSONArray();for(String x:photos)p.put(x);o.put("photos",p);
        }catch(Exception ignored){}return o;}
        static Draft from(JSONObject o){Draft d=new Draft();d.id=o.optString("id");d.client=o.optString("client");d.phone=o.optString("phone");d.location=o.optString("location");d.date=o.optString("date");d.system=o.optString("system","Hybrid");d.capacity=o.optString("capacity");d.phase=o.optString("phase","Single phase");d.organizer=o.optString("organizer");d.notes=o.optString("notes");d.installation=o.optBoolean("installation",true);d.transport=o.optBoolean("transport",false);JSONArray a=o.optJSONArray("items");if(a!=null)for(int i=0;i<a.length();i++)d.items.add(LineItem.from(a.optJSONObject(i)));JSONArray p=o.optJSONArray("photos");if(p!=null)for(int i=0;i<p.length();i++)d.photos.add(p.optString(i));return d;}
    }

    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(NAVY);getWindow().setNavigationBarColor(WHITE);seedCatalog();buildShell();showHome();}

